        from: usize,
        label: Label,
        to: usize,
    ) -> Result<(), Diagnostic> {
        budget.charge(function, 1, "factored automaton labelled movement")?;
        budget.reserve_vec(
            function,
            &mut self.nodes[from].moves,
            1,
            "factored automaton moves",
        )?;
        self.nodes[from].moves.push((label, to));
        #[cfg(test)]
        instrumentation::edge();
        Ok(())
    }

